/// <summary>
///     AVA <c>avaAvailPhysicalForRelease</c> method.
///     AVA - Schneider 22.08.2024
/// </summary>
/// <param name="_itemId">
///     <c>ItemId</c> as type
/// </param>
/// <param name="_inventDim">
///     <c>InventDim</c> as type
/// </param>
/// <returns>
///     <c>InventQtyAvailPhysical</c> as type
/// </returns>
static InventQtyAvailPhysical avaAvailPhysicalForRelease(   ItemId      _itemId, 
                                                            InventDim   _inventDim)
{
    InventQtyAvailPhysical  retVal;

    InventSum               locInventSum;
    InventDim               locInventDim;

    if(_inventDim.InventSiteId)
    {
        select sum(AvailPhysical)
        from locInventSum
        index hint ClosedItemDimIdx
        where   locInventSum.InventSiteId   == _inventDim.InventSiteId
            &&  locInventSum.Closed         == NoYes::No
            &&  locInventSum.ClosedQty      == NoYes::No
            &&  locInventSum.ItemId         == _itemId
            join locInventDim
            index hint DimIdIdx
            where   locInventDim.inventDimId    == locInventSum.InventDimId;

        retVal  = locInventSum.AvailPhysical;
    }
    else
    {
        retVal  = 0.0;
    }
    return retVal;
}

/// <summary>
///     AVA - Schneider 22.08.2024
///     AVA <c>avaPhysicalAvailAbilityForShipping</c> method.
/// </summary>
/// <param name="_itemId">
///     <c>ItemId</c> as type
/// </param>
/// <param name="_inventDim">
///     <c>InventDim</c> as type
/// </param>
/// <returns>
///     <c>AVAPhysicalAvailAbilityForShipping</c> as type
/// </returns>
static AVAPhysicalAvailAbilityForShipping avaPhysicalAvailAbilityForShipping(   ItemId      _itemId, 
                                                                                InventDim   _inventDim  )
{
    InventQtyAvailPhysical  retVal;

    InventSiteId            locInventSiteId;
    InventSite              locInventSite;
    boolean                 locInventSiteAbilityForShipping;
    InventLocationId        locInventLocationId;
    //InventLocation          locInventLocation;
    WHSInventStatusId       locWHSInventStatusId;
    //WHSInventStatus         locWHSInventStatus;
    EcoResItemColorName     locEcoResItemColorName;
    //EcoResColor             locEcoResColor;
    InventBatchId           locInventBatchId;
    //InventBatch             locInventBatch;

    InventSum               locInventSum;
    InventDim               locInventDim;
    WMSLocation             locWMSLocation;
    WHSZone                 locWHSZone;
    WHSZoneGroup            locWHSZoneGroup;

    if(_inventDim.InventSiteId != '' || _inventDim.InventLocationId != '')
    {
        if(_inventDim.InventSiteId)
        {
            locInventSiteId                 = _inventDim.InventSiteId;
            locInventSite                   = InventSite::find(locInventSiteId);
            locInventSiteAbilityForShipping = locInventSite.avaHasShippingAbility();
        }

        locInventLocationId             = _inventDim.InventLocationId;
        //locInventLocation                 = InventLocation::find(locInventLocationId);
        locWHSInventStatusId            = _inventDim.InventStatusId;
        //locWHSInventStatus              = WHSInventStatus::find(locWHSInventStatusId);
        locEcoResItemColorName          = _inventDim.InventColorId;
        //locEcoResColor                  = EcoResColor::findByName(locEcoResItemColorName);
        locInventBatchId                = _inventDim.InventBatchId;
        //locInventBatch                  = InventBatch::find(locInventBatchId, _itemId);
    }

    if(locInventSiteAbilityForShipping)
    {
        select sum(AvailPhysical)
        from    locInventSum
        index hint ItemDimIdx
        where   locInventSum.ItemId             == _itemId
            &&  locInventSum.InventSiteId       == locInventSiteId
            &&  locInventSum.InventLocationId   == locInventLocationId
            &&  locInventSum.AvailPhysical      != 0.0
            join    locInventDim
            where   locInventDim.inventDimId        == locInventSum.InventDimId
                &&  locInventDim.InventSiteId       == locInventSiteId
                &&  locInventDim.InventLocationId   == locInventLocationId
                &&  (locInventDim.InventStatusId     == locWHSInventStatusId || locWHSInventStatusId == '')
                &&  (locInventDim.InventColorId      == locEcoResItemColorName ||  locEcoResItemColorName == '')
                &&  locInventDim.wMSLocationId      != ''
                join    locWMSLocation
                where   locWMSLocation.wMSLocationId == locInventDim.wMSLocationId
                    join    locWHSZone
                    where   locWHSZone.ZoneId == locWMSLocation.ZoneId
                        join    locWHSZoneGroup
                        where   locWHSZoneGroup.ZoneGroupId == locWHSZone.ZoneGroupId
                            &&  locWHSZoneGroup.AVAWHSZoneGroupShipment;

        InventDimParm              inventDimParm;
        Qty                        reservedQty;

        inventDimParm.InventSiteIdFlag     = NoYes::Yes;
        inventDimParm.InventLocationIdFlag = NoYes::Yes;
        inventDimParm.InventStatusFlag   = NoYes::Yes;
        InventDimParm.InventColorIdFlag    = NoYes::Yes;

        InventOnHandQty     inventOnHandQty = InventOnHandQty::newItemDim(_ItemId,_inventDim,inventDimParm);
        reservedQty   =  inventOnHandQty.reservPhysical();

        retVal = locInventSum.AvailPhysical - reservedQty;

    }
    return retVal;
}

/// <summary>
///     AVA - Schneider 27.08.2024
///     AVA <c>avaPhysicalAvailAbilityForShippingCommon</c> method.
/// </summary>
/// <param name="_common">
///     <c>Common</c> as type
/// </param>
/// <returns>
///     <c>AVAPhysicalAvailAbilityForShipping</c> as type
/// </returns>
static AVAPhysicalAvailAbilityForShipping avaPhysicalAvailAbilityForShippingCommon(Common _common)
{
    InventQtyAvailPhysical  retVal;

    InventQtyAvailPhysical  locTmpVal;

    SalesLine               locSalesLine;
    SalesLine               locSalesLineComponent;

    InventTransferLine      locInventTransferLine;
    InventTransferLine      locInventTransferLineComponent;

    boolean                 locComponentFound;


    if(_common.RecId)
    {
        if(_common.TableId == tableNum(SalesLine))
        {
            locSalesLine = _common;
        }
        else if(_common.TableId == tableNum(InventTransferLine))
        {
            locInventTransferLine = _common;
        }
    }

    if(locSalesLine.RecId)
    {
        if(locSalesLine.AVAItemSet)
        {
            while select locSalesLineComponent
            where   locSalesLineComponent.AVAItemsetParent      == locSalesLine.InventTransId
                &&  locSalesLineComponent.AVAItemSetComponent   == NoYes::Yes
            {
                locTmpVal = InventSum::avaPhysicalAvailAbilityForShipping(locSalesLineComponent.ItemId, locSalesLineComponent.inventDim());
                locTmpVal = locTmpVal * locSalesLineComponent.AVAItemSetSerie / minOne(locSalesLineComponent.AVAItemSetCompQtyPerSerie);
                if(locTmpVal == 0)
                {
                    return 0.0;
                }
                if(!locComponentFound)
                {
                    retVal = locTmpVal;
                }
                else
                {
                    if(locTmpVal < retVal)
                    {
                        retVal = locTmpVal;
                    }
                }
                locComponentFound = true;
            }
        }
        else
        {
            retVal = InventSum::avaPhysicalAvailAbilityForShipping(locSalesLine.ItemId, locSalesLine.inventDim());
        }
    }
    else if(locInventTransferLine.RecId)
    {
        if(locInventTransferLine.AVAItemSet)
        {
            while select locInventTransferLineComponent
            where   locInventTransferLineComponent.AVAItemsetParent      == locInventTransferLine.InventTransId
                &&  locInventTransferLineComponent.AVAItemSetComponent   == NoYes::Yes
            {
                locTmpVal = InventSum::avaPhysicalAvailAbilityForShipping(locInventTransferLineComponent.ItemId, locInventTransferLineComponent.inventDim());
                locTmpVal = locTmpVal * locInventTransferLineComponent.AVAItemSetSerie / minOne(locInventTransferLineComponent.AVAItemSetCompQtyPerSerie);
                if(locTmpVal == 0)
                {
                    return 0.0;
                }
                if(!locComponentFound)
                {
                    retVal = locTmpVal;
                }
                else
                {
                    if(locTmpVal < retVal)
                    {
                        retVal = locTmpVal;
                    }
                }
                locComponentFound = true;
            }
        }
        else
        {
            retVal = InventSum::avaPhysicalAvailAbilityForShipping(locInventTransferLine.ItemId, locInventTransferLine.inventDim());
        }
    }

    return retVal;
}

/// <summary>
///     AVA <c>avaPhysicalReservedAbilityForShipping</c> method.
///     AVA - Schneider 22.08.2024
/// </summary>
/// <param name="_itemId">
///     <c>ItemId</c> as type
/// </param>
/// <param name="_inventDim">
///     <c>InventDim</c> as type
/// </param>
/// <returns>
///     <c>AVAPhysicalReservedAbilityForShipping</c> as type
/// </returns>
static AVAPhysicalReservedAbilityForShipping avaPhysicalReservedAbilityForShipping( ItemId      _itemId,
                                                                                    InventDim   _inventDim)
{
    InventQtyAvailPhysical  retVal;

    InventSiteId            locInventSiteId;
    InventSite              locInventSite;
    boolean                 locInventSiteAbilityForShipping;

    InventTransOrigin       locInventTransOrigin;
    InventTrans             locInventTrans;
    InventDim               locInventDimSearch;

    locInventSiteId                 = _inventDim.InventSiteId;
    locInventSite                   = InventSite::find(locInventSiteId);
    locInventSiteAbilityForShipping = locInventSite.avaHasShippingAbility();

    if(locInventSiteAbilityForShipping)
    {
        select sum(Qty)
        from    locInventTrans
            join    locInventTransOrigin
            where   locInventTransOrigin.RecId  == locInventTrans.InventTransOrigin
                &&  (   locInventTransOrigin.ReferenceCategory == InventTransType::Sales                    // Auftrag
                    ||  locInventTransOrigin.ReferenceCategory == InventTransType::TransferOrderShip    )   // Umlagerungsauftragslieferung
                &&  locInventTrans.ItemId       == _itemId
                &&  locInventTrans.StatusIssue  == StatusIssue::ReservPhysical
                join    locInventDimSearch
                where   locInventDimSearch.inventDimId      == locInventTrans.inventDimId
                    &&  locInventDimSearch.InventSiteId     == locInventSiteId
                    &&  locInventDimSearch.InventLocationId == _inventDim.InventLocationId;

        retVal = -locInventTrans.Qty;
    }

    return retVal;
}
